#include <vector>
#include <algorithm>

class Solution {
public:
    int solveNaive(const std::vector<int>& nums) {
        // Direct simulation logic
        int result = 0;
        for (int x : nums) {
            result += x;
        }
        return result;
    }
};

#include <vector>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    int solveOptimal(const std::vector<int>& nums) {
        // Optimal C++ solution for: Online Majority Element In Subarray
        std::unordered_map<int, int> countMap;
        for (int num : nums) {
            countMap[num]++;
        }
        return countMap.size();
    }
};
